+export function reply_blessings_you_family_church_country() {
+  "The four a blessing goes out to when it is meant for the whole of somebody's life: them, their family, their church and their country. Each one goes on the list of blessings separately, so a word already there is not said twice.";
+  let blessed = ["you", "your family", "your church", "your country"];
+  return blessed;
+}
